   136	_idn2_label_test (int what, const uint32_t * label, size_t llen)
   137	{
   138	  if (what & TEST_NFC)
   139	    {
   140	      size_t plen;
   141	      uint32_t *p = u32_normalize (UNINORM_NFC, label, llen,
   142	                                   NULL, &plen);
   143	      int ok;
   144	      if (p == NULL)
   145	        {
   146	          if (errno == ENOMEM)
   147	            return IDN2_MALLOC;
   148	          return IDN2_NFC;
   149	        }
   150	      ok = llen == plen && memcmp (label, p, plen * sizeof (*label)) == 0;
   151	      free (p);
   152	      if (!ok)
   153	        return IDN2_NOT_NFC;
   154	    }
   155	
   156	  if (what & TEST_2HYPHEN)
   157	    {
   158	      if (llen >= 4 && label[2] == '-' && label[3] == '-')
   159	        return IDN2_2HYPHEN;
   160	    }
   161	
   162	  if (what & TEST_HYPHEN_STARTEND)
   163	    {
   164	      if (llen > 0 && (label[0] == '-' || label[llen - 1] == '-'))
   165	        return IDN2_HYPHEN_STARTEND;
   166	    }
   167	
   168	  if (what & TEST_LEADING_COMBINING)
   169	    {
   170	      if (llen > 0 && uc_is_general_category (label[0], UC_CATEGORY_M))
   171	        return IDN2_LEADING_COMBINING;
   172	    }
   173	
   174	  if (what & TEST_DISALLOWED)
   175	    {
   176	      size_t i;
   177	      for (i = 0; i < llen; i++)
   178	        if (_idn2_disallowed_p (label[i]))
   179	          {
   180	            if ((what & (TEST_TRANSITIONAL | TEST_NONTRANSITIONAL)) &&
   181	                (what & TEST_ALLOW_STD3_DISALLOWED))
   182	            {
   183	              IDNAMap map;
   184	              get_idna_map (label[i], &map);
   185	              if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID) ||
   186	                  map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
   187	              continue;
   188	
   189	            }
   190	
   191	            return IDN2_DISALLOWED;
   192	          }
   193	    }
   194	
   195	  if (what & TEST_CONTEXTJ)
   196	    {
   197	      size_t i;
   198	      for (i = 0; i < llen; i++)
   199	        if (_idn2_contextj_p (label[i]))
   200	          return IDN2_CONTEXTJ;
   201	    }
   202	
   203	  if (what & TEST_CONTEXTJ_RULE)
   204	    {
   205	      size_t i;
   206	      int rc;
   207	
   208	      for (i = 0; i < llen; i++)
   209	        {
   210	          rc = _idn2_contextj_rule (label, llen, i);
   211	          if (rc != IDN2_OK)
   212	            return rc;
   213	        }
   214	    }
   215	
   216	  if (what & TEST_CONTEXTO)
   217	    {
   218	      size_t i;
   219	      for (i = 0; i < llen; i++)
   220	        if (_idn2_contexto_p (label[i]))
   221	          return IDN2_CONTEXTO;
   222	    }
   223	
   224	  if (what & TEST_CONTEXTO_WITH_RULE)
   225	    {
   226	      size_t i;
   227	      for (i = 0; i < llen; i++)
   228	        if (_idn2_contexto_p (label[i])
   229	            && !_idn2_contexto_with_rule (label[i]))
   230	          return IDN2_CONTEXTO_NO_RULE;
   231	    }
   232	
   233	  if (what & TEST_CONTEXTO_RULE)
   234	    {
   235	      size_t i;
   236	      int rc;
   237	
   238	      for (i = 0; i < llen; i++)
   239	        {
   240	          rc = _idn2_contexto_rule (label, llen, i);
   241	          if (rc != IDN2_OK)
   242	            return rc;
   243	        }
   244	    }
   245	
   246	  if (what & TEST_UNASSIGNED)
   247	    {
   248	      size_t i;
   249	      for (i = 0; i < llen; i++)
   250	        if (_idn2_unassigned_p (label[i]))
   251	          return IDN2_UNASSIGNED;
   252	    }
   253	
   254	  if (what & TEST_BIDI)
   255	    {
   256	      int rc = _idn2_bidi (label, llen);
   257	      if (rc != IDN2_OK)
   258	        return rc;
   259	    }
   260	
   261	  if (what & (TEST_TRANSITIONAL | TEST_NONTRANSITIONAL))
   262	    {
   263	      size_t i;
   264	      int transitional = what & TEST_TRANSITIONAL;
   265	
   266	      /* TR46: 4. The label must not contain a U+002E ( . ) FULL STOP */
   267	      for (i = 0; i < llen; i++)
   268	        if (label[i] == 0x002E)
   269	          return IDN2_DOT_IN_LABEL;
   270	
   271	      /* TR46: 6. Each code point in the label must only have certain status
   272	       * values according to Section 5, IDNA Mapping Table:
   273	       *    a. For Transitional Processing, each value must be valid.
   274	       *    b. For Nontransitional Processing, each value must be either valid or deviation. */
   275	      for (i = 0; i < llen; i++)
   276	        {
   277	          IDNAMap map;
   278	
   279	          get_idna_map (label[i], &map);
   280	
   281	          if (map_is (&map, TR46_FLG_VALID) ||
   282	              (!transitional && map_is (&map, TR46_FLG_DEVIATION)))
   283	            continue;
   284	
   285	          if (what & TEST_ALLOW_STD3_DISALLOWED &&
   286	              (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID) ||
   287	               map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED)))
   288	            continue;
   289	
   290	          return transitional ? IDN2_INVALID_TRANSITIONAL :
   291	            IDN2_INVALID_NONTRANSITIONAL;
   292	        }
   293	    }
   294	
   295	  return IDN2_OK;
   296	}
